AdaptiveCardNotificationTemplate.Body:
{
"type": "AdaptiveCard",
"version": "1.2",
"body": [
{
"type": "TextBlock",
"text": "#if ($requesterName)$requesterName #{else}The system #{end} has assigned the following work item to you: _${workItemName}_.",
"wrap": true
}
],
"actions": [
{
"type": "Action.OpenUrl",
"title": "$adaptiveCardButtonName",
"url": "$webUrl"
}
]
}

{
  "type": "AdaptiveCard",
  "version": "1.2",
  "body": [
    {
      "type": "TextBlock",
     "text": "#if ($requesterName) _${requesterName}_ #{else} The system #{end} has removed the following work item from your queue: _${workItemName}_.",
     "wrap": true
    }
  ],
  "actions": [
    {
     "type": "Action.OpenUrl",
     "title": "$adaptiveCardButtonName",
     "url": "$webUrl"
   }
  ]
}

{
    "type": "AdaptiveCard",
    "version": "1.2",
    "body": [
    {
      "type": "TextBlock",
      "text": "$requester forwarded work item _${workItemName}_ from _${previousOwner}_ to **${newOwner}** on $spTools.formatDate($forwardDate,3,1)",
      "wrap": true,
      "horizontalAlignment": "Left"
    },
#if ($commentText)

    {
      "type": "Table",
      "columns": [
        {
          "width": 1
        },
        {
          "width": 1
        }
      ],
      "rows": [
        {
          "type": "TableRow",
          "cells": [
            {
              "type": "TableCell",
              "items": [
                {
                  "type": "TextBlock",
                  "text": "Comments",
                  "wrap": true
                }
              ]
            },
            {
              "type": "TableCell",
              "items": [
                {
                  "type": "TextBlock",
                  "text": "$commentText",
                  "wrap": true
                }
              ]
            }
          ]
        }
      ],
      "firstRowAsHeaders": false,
      "roundedCorners": true,
      "spacing": "Small"
    },
#end
    {
     "type": "ActionSet",
     "actions": [
       {
         "type": "Action.OpenUrl",
         "title": "$adaptiveCardButtonName",
         "url": "$webUrl"
       }
     ]
    }
   ]
}


{
    "type": "AdaptiveCard",
    "$schema": "https://adaptivecards.io/schemas/adaptive-card.json",
    "version": "1.5",
    "body": [
        {
            "type": "TextBlock",
            "text": "_${launcher}_ is requesting the following changes for **${identityDisplayName}**",
            "wrap": true,
            "horizontalAlignment": "Left"
        }
#if  ( $approvalSet.items )
  #foreach ($approvalItem in $approvalSet.items)
         ,
        {
            "type": "Table",
            "columns": [
                {
                    "width": 1
                },
                {
                    "width": 1
                }
            ],
            "rows": [
                {
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Application",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "$approvalItem.applicationName",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #if ( $approvalItem.nativeIdentity )
                ,{
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Account",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "$approvalItem.nativeIdentity",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #end
                ,{
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Operation",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "$approvalItem.operation",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #if ( $approvalItem.displayName )
      #set ($attribute = $approvalItem.displayName)
    #elseif ( $approvalItem.name )
      #set ($attribute = $approvalItem.name)
    #end
    #if ($attribute)
                ,{
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Attribute",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "$attribute",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #end
    #if ( $approvalItem.displayValue )
      #set ($values = $approvalItem.displayValue)
    #elseif ( $approvalItem.csv )
      #set ($values = $approvalItem.csv)
    #end
    #if ($values)
                ,{
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Values(s)",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "${values}",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #end
    #if ( $item.level )
                ,{
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Priority",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "$item.level",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #end
    #if ( $approvalItem.requesterComments )
                ,{
                    "type": "TableRow",
                    "cells": [
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Requester Comments",
                                    "wrap": true
                                }
                            ]
                        },
                        {
                            "type": "TableCell",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "$approvalItem.requesterComments",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
    #end

            ],
            "firstRowAsHeaders": false,
            "roundedCorners": true,
            "spacing": "ExtraLarge"
        }
  #end
#end
        ,
        {
            "type": "ActionSet",
            "actions": [
              {
                "type": "Action.OpenUrl",
                "title": "$adaptiveCardButtonName",
                "url": "$webUrl"
             }
           ]
        }
    ]
}
